  while (tc--) {
    int k;
    cin >> k;
    unordered_map<int, int> frequencies;
    int total_operations = 0;
    for (int i = 0; i < k; i++) {
      int value, points;
      cin >> value >> points;
      frequencies[value] += points;
    }
    perform_operations(frequencies);
    cout << total_operations << endl;
  }
  return 0;
}

void perform_operations(unordered_map<int, int>& frequencies) {
  for (auto it = frequencies.begin(); it != frequencies.end();) {
    if (it->second <= 1) {
      it = frequencies.erase(it);
      continue;
    }
    it->second -= 2;
    total_operations++;
    frequencies[it->first + 1]++;
    frequencies[it->first - 1]++;
    it++;
  }
  perform_operations(frequencies);
}

