const int MAXN = 105;
int C, N, curr;
int C[MAXN][MAXN];
double opt[MAXN][MAXN][MAXN];
bool used[MAXN][MAXN][MAXN];

double Calculate(int a, int b) {
    if (C[a][b] != -1) return C[a][b];
    if (b == 0 || a == b) return C[a][b] = 1;
    return C[a][b] = Calculate(a - 1, b - 1) + Calculate(a - 1, b);
}

double Search(int c, int n, int used) {
    if (used & (1 << curr)) return opt[c][n][curr];
    if (c < 0 || n < 0) return 0;
    if (c == 0) return opt[c][n][curr] = n;

    double& ans = opt[c][n][curr];
    used |= (1 << curr);

    for (int i = 0; i <= c; i++) {
        double p = Calculate(c, i) * (1.0 / double(C));
        double taken = Search(c - i, n - 1, used);
        double left = Search(c - i, n, used);

        ans += p * (1 + taken + left);
    }
    return ans;
}

void Prefill() {
    for (int i = 0; i < MAXN; i++) {
        C[i][0] = C[i][i] = 1;
        for (int j = 1; j < i; j++) {
            C[i][j] = -1;
        }
    }
}

int main() {
    cin >> C >> N;
    Prefill();
    cout << fixed << setprecision(10) << Search(C, N, 0) << endl;
}

