const int maxn = 1000;
int n, L;
double x[maxn], y[maxn];

int simulate(int p, double x0, double y0, double L) {
    double min_pos = 1e9, max_d = 0;
    int next = -1;
    for (int i = 0; i < n; i++) {
        if (i == p) continue;
        double dx = x[i] - x0, dy = y[i] - y0;
        double d = sqrt(dx * dx + dy * dy);
        if (d <= L && d > max_d) {
            double ang = atan2(dy, dx);
            if (ang < min_pos) {
                min_pos = ang;
                max_d = d;
                next = i;
            }
        }
    }
    if (next == -1) return 1;
    return 1 + simulate(next, x0 + x[next] - x0, y0 + y[next] - y0, L - max_d);
}

int main(int argc, char **argv) {
    int t;
    freopen(argv[1], "r", stdin);
    freopen(argv[2], "w", stdout);
    cin >> t;
    while (t--) {
        cin >> n >> L;
        for (int i = 0; i < n; i++) cin >> x[i] >> y[i];
        int R = 0;
        while (L >= 0) {
            int r = 0;
            for (int i = 0; i < n; i++) {
                r = max(r, simulate(i, x[i], y[i], L));
            }
            R = max(R, r);
            L -= 0.1;
        }
        cout << R << endl;
    }
    return 0;
}
