    columnIndices.resize(numberOfColumns * numberOfRows);
    rowIndices.resize(numberOfColumns * numberOfRows);
    pathSteps.resize(numberOfColumns * numberOfRows, -1);
    previousSteps.resize(numberOfColumns * numberOfRows, -1);
    possibleDirections.resize(numberOfColumns * numberOfRows, -1);
    for (int index = 0; index < numberOfRows; index++)
      for (int j = 0; j < numberOfColumns; j++) {
        char symbol;
        cin >> symbol;
        columnIndices[index * numberOfColumns + j] = j;
        rowIndices[index * numberOfColumns + j] = index;
        if (index == 0 || index == numberOfRows - 1 || j == 0 || j == numberOfColumns - 1) visited[{index, j}] = true;
        else if (symbol == '#') visited[{index, j}] = true;
      }
    queue<int> queue;
    pathSteps[0] = 0;
    queue.push(0);
    while (!queue.empty()) {
      index = queue.front();
      queue.pop();
      if (columnIndices[index] == targetColumn && rowIndices[index] == targetRow) break;
      for (int dx = -1; dx <= 1; dx++)
        for (int dy = -1; dy <= 1; dy++) {
          if (dx == 0 && dy == 0) continue;
          int nextColumn = columnIndices[index] + dx;
          int nextRow = rowIndices[index] + dy;
          if (nextColumn < 0 || nextColumn >= numberOfColumns || nextRow < 0 || nextRow >= numberOfRows || visited[{nextRow, nextColumn}]) continue;
          visited[{nextRow, nextColumn}] = true;
          pathSteps[nextRow * numberOfColumns + nextColumn] = pathSteps[index] + 1;
          previousSteps[nextRow * numberOfColumns + nextColumn] = dx + 1;
          possibleDirections[nextRow * numberOfColumns + nextColumn] = index;
          queue.push(nextRow * numberOfColumns + nextColumn);
        }
    }
    if (pathSteps[targetRow * numberOfColumns + targetColumn] == -1) cout << "No path\n";
    else {
      int currentStep = targetRow * numberOfColumns + targetColumn;
      while (currentStep != 0) {
        if (previousSteps[currentStep] == 1) directions += 'D';
        else if (previousSteps[currentStep] == -1) directions += 'U';
        else if (previousSteps[currentStep] == 2) directions += 'R';
        else if (previousSteps[currentStep] == -2) directions += 'L';
        currentStep = possibleDirections[currentStep];
      }
      reverse(directions.begin(), directions.end());
      cout << directions << endl;
    }
  }
  return 0;
