// A function to convert a decimal number to a given base
vector<int> convert_to_base(int num, int base) {
  vector<int> digits;
  while (num > 0) {
    digits.push_back(num % base);
    num /= base;
  }
  return digits;
}

// A function to check if a number is valid in a given base
bool is_valid_number(vector<int> digits, int base) {
  for (int digit : digits) {
