LL intT gcd(LL intT a, LL intT b) { return b ? gcd(b, a % b) : a; }
LL intT eGCD(LL intT a, LL intT b, LL intT& x, LL intT& y) {
  if (b == 0) {
    x = 1, y = 0;
    return a;
  }
  LL intT x1, y1;
  LL intT g = eGCD(b, a % b, x1, y1);
  x = y1, y = x1 - a / b * y1;
  return g;
}
LL intT inverse(LL intT a, LL intT p) {
  LL intT x, y;
  eGCD(a, p, x, y);
  return (x % p + p) % p;
}

int grid[205][205], wp[205][205], dp[205][205], vis[205][205];
int di[] = {-1, 1, 0, 0};
int dj[] = {0, 0, -1, 1};

void solve() {
  int h, w, m, sz = 0, c = 0;
  scanf("%d %d %d", &h, &w, &m);
  priority_queue<pair<int, PII>> pq;
  memset(vis, 0, sizeof vis);
  for (int i = 0; i < h; ++i) {
    for (int j = 0; j < w; ++j) {
      scanf("%d", &grid[i][j]);
    }
  }
  for (int i = 0; i < h; ++i) {
    if (grid[i][0] > m) pq.push(MP(-grid[i][0], MP(i, 0)));
    vis[i][0] = 1;
    grid[i][w - 1] -= m;
    if (grid[i][w - 1] > 0) pq.push(MP(-grid[i][w - 1], MP(i, w - 1)));
    vis[i][w - 1] = 1;
  }
  for (int j = 0; j < w; ++j) {
    if (grid[0][j] > m) pq.push(MP(-grid[0][j], MP(0, j)));
    vis[0][j] = 1;
    grid[h - 1][j] -= m;
    if (grid[h - 1][j] > 0) pq.push(MP(-grid[h - 1][j], MP(h - 1, j)));
    vis[h - 1][j] = 1;
  }
  while (!pq.empty()) {
    int u = pq.top().second.first, v = pq.top().second.second;
    int cost = -pq.top().first;
    pq.pop();
    if (vis[u][v] == 2) continue;
    vis[u][v] = 2;
    wp[u][v] = cost;
    for (int p = 0; p < 4; ++p) {
      int x = u + di[p], y = v + dj[p];
      if (x < 0 || x >= h || y < 0 || y >= w) continue;
      if (!vis[x][y] && grid[x][y] - cost > 0) {
        pq.push(MP(-(grid[x][y] - cost), MP(x, y)));
      }
    }
  }
  for (int i = 0; i < h; ++i) {
    for (int j = 0; j < w; ++j) {
      dp[i][j] = max(dp[i][j], wp[i][j] + grid[i][j]);
      if (i) dp[i][j] = max(dp[i][j], dp[i - 1][j]);
      if (j) dp[i][j] = max(dp[i][j], dp[i][j - 1]);
    }
  }
  for (int i = h - 1; i >= 0; --i) {
    for (int j = w - 1; j >= 0; --j) {
      if (i < h - 1) dp[i][j] = max(dp[i][j], dp[i + 1][j]);
      if (j < w - 1) dp[i][j] = max(dp[i][j], dp[i][j + 1]);
    }
  }
  int ans = 0;
  for (int i = 0; i < h; ++i) {
    for (int j = 0; j < w; ++j) {
      ans = max(ans, dp[i][j]);
    }
  }
  printf("Case %d: %d\n", ++c, ans);
}

