vector<string> color_strings;
vector<int> color;
vector<bool> first_seen;

void generateColors() {
  unordered_map<string, int> color_map;
  int current_color = 0;
  for (const auto& c : color_strings) {
    auto& color_index = color_map[c];
    if (color_index == 0) {
      color_index = current_color++;
      first_seen.push_back(true);
    } else {
      first_seen.push_back(false);
    }
    color.push_back(color_index);
  }
}

int calculateHeight(int current_mask) {
  vector<int> heights(color.size(), 0);
  for (size_t i = 0; i < color.size(); i++) {
    if ((current_mask & (1 << i)) != 0) {
      heights[color[i]]++;
    } else {
      heights[color[i]] = max(heights[color[i]], static_cast<int>(first_seen[i]) + 1);
    }
  }
  return *max_element(heights.begin(), heights.end());
}

int solve() {
  int number_of_colors;
  cin >> number_of_colors;
  color_strings.resize(number_of_colors);
  for (auto& c : color_strings) cin >> c;
  int mid_point = (number_of_colors + 1) / 2;
  generateColors();
  vector<int> memoization_table(1 << mid_point, -1);
  memoization_table[0] = 0;
  for (int mask = 0; mask < (1 << mid_point); mask++) {
    memoization_table[mask] = calculateHeight(mask);
    for (int i = 0; i < mid_point; i++) {
      if (((mask >> i) & 1) == 0) {
        if (memoization_table[mask] > memoization_table[mask | (1 << i)])
          memoization_table[mask | (1 << i)] = memoization_table[mask];
      }
    }
  }
  return memoization_table[(1 << mid_point) - 1];
}

