long double probability_of_heads, target_probability, current_probability;

// Function to calculate the probability of getting target probability
long double calculate_probability(int flips_remaining, long double current_probability) {
  // Base case: no more flips left
  if (flips_remaining == 0) {
    return current_probability == target_probability;
  }

  // Recursively calculate probabilities for getting heads and tails
  long double probability_heads = (1 - probability_of_heads) * calculate_probability(flips_remaining - 1, current_probability + probability_of_heads);
  long double probability_tails = probability_of_heads * calculate_probability(flips_remaining - 1, current_probability - probability_of_heads);

  // Return the probability of getting target probability after this flip
  return probability_heads + probability_tails;
}

