int pathCover(int n, const bool mat[][MAXN], int* pre, int* next) {
    int i, j, k, minf, q[MAXN], prev[MAXN];
    bool flow[MAXN];
    for (i = 1; i <= n; i++) {
        pre[i] = 0;
        next[i] = 0;
    }
    for (i = 1; i <= n; i++) {
        flow[i] = false;
    }
    minf = INT_MAX;
    for (j = 1; j <= n; j++) {
        if (!flow[j]) {
            for (k = 1; k <= n; k++) {
                if (!flow[k] && mat[j][k]) {
                    if (minf > a[j][k]) {
                        minf = a[j][k];
                    }
                }
            }
        }
    }
    for (j = 1; j <= n; j++) {
        if (!flow[j]) {
            for (k = 1; k <= n; k++) {
                if (!flow[k] && mat[j][k]) {
                    a[j][k] -= minf;
                }
            }
        }
    }
    do {
        q[0] = 0;
        for (i = 1; i <= n; i++) {
            if (!flow[i]) {
                q[0]++;
                q[q[0]] = i;
            }
        }
        j = 0;
        while (j < q[0]) {
            u = q[++j];
            for (k = 1; k <= n; k++) {
                if (!flow[u] && !flow[k] && mat[u][k]) {
                    c = a[u][k] - prev[u] + prev[k];
                    if (c == 0) {
                        if (next[k] == 0) {
                            x = u;
                            y = k;
                            goto next;
                        } else {
                            prev[next[k]] = u;
                            q[++q[0]] = next[k];
                        }
                    }
                }
            }
        }
        if (x != 0) {
            do {
                prev[y] = x;
                i = next[y];
                next[y] = x;
                x = i;
                y = pre[x];
            } while (x != 0);
            x = 0;
            y = 0;
            minf = INT_MAX;
            for (j = 1; j <= n; j++) {
                if (!flow[j]) {
                    if (prev[j] != 0) {
                        a[prev[j]][j] = a[u][k];
                        if (minf > a[prev[j]][j]) {
                            minf = a[prev[j]][j];
                        }
                    }
                }
            }
            for (j = 1; j <= n; j++) {
                if (!flow[j]) {
                    if (prev[j] != 0) {
                        a[prev[j]][j] -= minf;
                    } else {
                        a[u][k] += minf;
                    }
                }
            }
        } while (x != 0);
        for (i = 1; i <= n; i++) {
            if (!flow[i]) {
                for (j = 1; j <= n; j++) {
                    if (mat[i][j] && a[i][j] == 0 && flow[j]) {
                        prev[i] = j;
                        next[j] = i;
                        flow[i] = true;
                        break;
                    }
                }
            }
        }
    } while (x != 0);
    c = 0;
    for (i = 1; i <= n; i++) {
        if (flow[i]) {
            c++;
        }
    }
    return c;
}

