template <typename T>
struct Edge {
    int destination;
    T weight;
    Edge(int destination, T weight) : destination(destination), weight(weight) {}
};

template <typename T>
class Dijkstra {
private:
    int vertexCount;
    vector<T> distances;
    vector<vector<Edge<T>>> adjacencyList;

public:
    Dijkstra(int vertexCount) : vertexCount(vertexCount) {
        distances.assign(vertexCount, -1);
        adjacencyList.resize(vertexCount);
    }

    void addEdge(int source, int destination, T weight) {
        adjacencyList[source].emplace_back(destination, weight);
    }

    void relax(int source) {
        priority_queue<pair<T, int>> pq;
        pq.emplace(0, source);
        distances[source] = 0;

        while (!pq.empty()) {
            auto [distance, vertex] = pq.top(); pq.pop();
            if (-distance > distances[vertex]) continue;

            for (auto& edge : adjacencyList[vertex]) {
                T newDistance = distance - edge.weight;
                if (newDistance > distances[edge.destination]) {
                    distances[edge.destination] = newDistance;
                    pq.emplace(newDistance, edge.destination);
                }
            }
        }
    }

    T getDistance(int vertex) {
        return distances[vertex];
    }
};

int main() {
    int testCases; cin >> testCases;
