        vector<pair<int, int>> points(n);
        for (int i = 0; i < n; ++i) {
            int x, y, z, w, p, q; cin >> x >> y >> z >> w >> p >> q;
            points[i] = {x + y + z + w + p + q, i};
        }
        sort(points.begin(), points.end());

        Dijkstra<long double> dijkstra(n);
        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                long double distance = sqrtl(
                    pow(points[i].first - points[j].first, 2) +
                    pow(points[i].second - points[j].second, 2));
                dijkstra.addEdge(points[i].second, points[j].second, distance);
                dijkstra.addEdge(points[j].second, points[i].second, distance);
            }
        }

        dijkstra.relax(0);
        cout << fixed << setprecision(10) << dijkstra.getDistance(1) << endl;
    }

    return 0;
}

