    cout << "Distances from city " << i + 1 << ":\n";
    for (int j = 0; j < cities; j++) {
      int distance;
      cout << "To city " << j + 1 << ": ";
      cin >> distance;
      distances[i][j] = distance;
    }
  }
  if (cities == 1) {  // If we have just one city, there's no point in going anywhere
    if (distances[0][0] == 0) {
      cout << "Well, you're already where you need to be!\n";
    } else {
      cout << "Unfortunately, you're stuck in this city.\n";
    }
    return 0;
  }
  set<int> explored[cities];  // Keep track of which cities we've already visited
  for (int i = 0; i < cities; i++) {
    explored[i].insert(i);  // Initially, we've only been to our starting point
  }
  queue<int> nextCities;
  nextCities.push(0);  // Let's start our journey in the first city
  int hops = 0;
  while (!nextCities.empty()) {  // As long as we have cities to explore
    int currentCity = nextCities.front();
    nextCities.pop();
    if (distances[currentCity][0] == distances[currentCity][cities - 1]) {  // If we've found a path to our destination
      cout << "Congratulations! It took you " << hops << " hops to get there.\n";
      return 0;
    }
    for (int i = 0; i < cities; i++) {
      if (i == currentCity || explored[currentCity].find(i) != explored[currentCity].end()) continue;  // Skip ourselves and already-explored cities
      if (distances[currentCity][i] + distances[i][0] == distances[currentCity][cities - 1]) {  // If this city is a hop away from our destination
        nextCities.push(i);
        explored[currentCity].insert(i);
        hops++;
      }
    }
  }
  cout << "Sorry, it seems impossible to reach your destination.\n";
  return 0;
}
