    for (int j = 1; j < 2 * width; ++j) {
      int node_id = 2 + 2 * i + j;
      if (i % 2 == 0 || j % 2 == 0) {
        connect_nodes(node_id, node_id + 1, 1);
        connect_nodes(node_id + 1, node_id, 1);
      } else {
        connect_nodes(node_id, node_id + 1, 1);
        connect_nodes(node_id, node_id + 2 * width, 1);
      }
    }
  }
