  FN = n;
  for (int i = 1; i < 2 * height; ++i) {
    for (int j = 1; j < 2 * width; ++j) {
      int node_id = 2 + 2 * i + j;
      if (!block[i][j]) {
        if (i % 2 == 0 || j % 2 == 0) {
          connect_nodes(ST, node_id + 1, 1);
          connect_nodes(node_id, FN, 1);
        }
      }
    }
  }
}

void find_maximum_flow() {
