const int MOD = pow(10, 9) + 7;
const int Limit = 100007;
int factorial[Limit], inverseFactorial[Limit];
int primes[Limit];
long long powMod(long long x, long long y) {
    long long remainder = 1;
    while (y) {
        if (y & 1) remainder = remainder * x % MOD;
        x = x * x % MOD;
        y >>= 1;
    }
    return remainder;
}
void calculateFactorials() {
    factorial[0] = 1;
    for (int i = 1; i < Limit; ++i) factorial[i] = (1LL * i * factorial[i - 1]) % MOD;
    inverseFactorial[Limit - 1] = powMod(factorial[Limit - 1], MOD - 2);
    for (int i = Limit - 2; i >= 0; --i) inverseFactorial[i] = (1LL * inverseFactorial[i + 1] * (i + 1)) % MOD;
}
int combinations(long long n, int r) {
    if (n < r) return 0;
    return (1LL * factorial[n] * inverseFactorial[r] % MOD * inverseFactorial[n - r]) % MOD;
}
void sieve() {
    primes[0] = primes[1] = 1;
    for (int i = 2; i < Limit; ++i) {
        if (!primes[i]) {
            for (int j = i + i; j < Limit; j += i) primes[j] = 1;
        }
    }
}
int mobius(int x) {
    int result = 1;
    for (int i = 2; i * i <= x; ++i) {
        if (x % i == 0) {
            result = -result;
            if (x % i % i == 0) return 0;
            while (x % i == 0) x /= i;
        }
    }
    if (x > 1) result = -result;
    return result;
}
int main() {
    sieve();
    calculateFactorials();
    for (int n = 1; n <= 100000; ++n) {
        int m = max(n / 2 - 1, 1);
        long long result = 0;
        for (int d = 1; d <= m; ++d) {
            if (n % d == 0) {
                int a = d;
                int b = n / d;
                if (a > b) swap(a, b);
                if (primes[a] || primes[b]) continue;
                int signA = mobius(a);
                int signB = mobius(b);
                if (signA == signB) continue;
                int temp = (signB * 1LL * combinations(n / b, m) % MOD + MOD) % MOD;
                result = (result + 1LL * temp * combinations(a - 1, m - 1) % MOD) % MOD;
            }
        }
        if (result < 0) printf("%d %lld\n", n, result + MOD);
    }
    return 0;
}

