Re *parse2(string s) {
    Re *e = nullptr, *t, *p = nullptr;
    stack<Re *> st;
    forloop(i, 0, elementCount(s)) {
        switch (s[i]) {
            case '(':
                st.emplace(e);
                e = t = nullptr;
                break;
            case ')':
                t = st.top();
                st.pop();
                if (st.empty()) return t;
                p = st.top();
                st.pop();
                st.emplace(concatenate(p, t));
                break;
            case '.':
                if (st.empty()) st.emplace(e);
                p = st.top();
                st.pop();
                t = e;
                e = concatenate(p, t);
                st.emplace(e);
                break;
            case '*':
                t = st.top();
                st.pop();
                st.emplace(closure(t));
                break;
            default:
                e = digit(s[i]);
                if (!st.empty()) {
                    p = st.top();
                    st.pop();
                    st.emplace(concatenate(p, e));
                } else
                    st.emplace(e);
