    int packages = 0;
    while (true) {
        bool all_exhausted = true;
        for (int i = 0; i < N; i++) {
            if (current_item[i] < P) all_exhausted = false;
        }
        if (all_exhausted) break;
        int min_quantity = Q[0][current_item[0]];
        int min_idx = 0;
        for (int i = 1; i < N; i++) {
            if (Q[i][current_item[i]] < min_quantity) {
                min_quantity = Q[i][current_item[i]];
                min_idx = i;
            }
        }
