vector<int> find_convex_hull(int num_points) {
  vector<int> hull;
  for (int i = 0; i < num_points; i++) {
    while (hull.size() >= 2 &&
           is_counterclockwise(hull[hull.size() - 2], hull.back(), i))
      hull.pop_back();
    hull.push_back(i);
