    int num_events = events.size();
    for (int i = 0; i < num_events; i++) {
      int u = events[i].second.first, v = events[i].second.second;
      time = (int)events[i].first;
      if (directions[u] == directions[v]) {
        if (colors[find_parent(u)] == colors[find_parent(v)]) {
          result = events[i].first;
          break;
        }
      } else {
        if (last_time_seen[u] != time) last_time_seen[u] = time, merge_sets(u, 0), merge_sets(v, 1);
        if (last_time_seen[v] != time) last_time_seen[v] = time, merge_sets(v, 0), merge_sets(u, 1);
      }
    }
    if (i == num_events)
      puts("No collision.");
    else
      printf("Collision after %.9lf seconds.\n", result);
  }
  return 0;
}

