bool feasible(double R) {
    for (long long mask = 1; mask < total; mask <<= 1) {
        int i = __builtin_ctzll(mask);
        vertex a = initialize(x_coords[i], y_coords[i], radii[i]+R, radii[i]+R);
        for (int j = i+1; j < num_vertices; ++j) {
            if ((mask >> j) & 1) {
                vertex b = initialize(x_coords[j], y_coords[j], radii[j]+R, radii[j]+R);
                if (distance(a, b) > 2*R+tolerance) return false;
                a = initialize(a, b, R, R);
