const int N = 1024;
int n, best;
double R, x[N], y[N];

double dst(int i, int j) { return sqrt((x[i] - x[j]) * (x[i] - x[j]) + (y[i] - y[j]) * (y[i] - y[j])); }

int better(int i, int j, int k, double dir) {
  if (dst(i, k) > dst(j, k))
    return j;
  double a1 = atan2(y[i] - y[k], x[i] - x[k]), a2 = atan2(y[j] - y[k], x[j] - x[k]), d = (a2 - a1) / 3.14159265358979323846;
  if (d < 0) d += 2;
  if (fabs(d - 1) < fabs(d - 3))
    return j;
  else
    return i;
}
int go(int k, double r, double dir) {
  int ret = 1;
  for (int i = 0; i < n; i++) {
    if (i != k) {
      double d = dst(i, k);
      if (d < r) {
        int p = better(i, k, k, dir);
        ret = max(ret, 1 + go(p, r - d, atan2(y[p] - y[k], x[p] - x[k])));
      }
    }
  }
  return ret;
}
