  int j;
  cin >> j;
  while (j--) {
    cin >> n >> R;
    for (int i = 0; i < n; i++) cin >> x[i] >> y[i];
    best = 0;
    for (double r = 0.5; r <= R; r += 0.5) { best = max(best, go(0, r, 0)); }
    printf("%d\n", best);
  }
  return 0;
}

