struct userActivity
{
    int row, column, cost;
    userActivity(int Row = 0, int Column = 0, int Cost = 0) : row(Row), column(Column), cost(Cost) {}
    bool operator<(const userActivity &other) const { return cost < other.cost; }
};

int calculateOptimalCost(int currentColumn, vector<userActivity> &userActivities)
{
    if (currentColumn == columnCount)
    {
        int totalCost = 0;
        for (auto &activity : userActivities)
            totalCost += activity.cost;

        return totalCost;
    }

    int minimumCost = 100; // Initialize with a large value
    vector<userActivity> userActivities1, userActivities2;

    for (auto &activity : userActivities)
    {
        if (activity.row + 1 < userCount && userActivities[activity.row][currentColumn] != desiredActivities[activity.row][currentColumn] && 
            userActivities[activity.row + 1][currentColumn] != desiredActivities[activity.row + 1][currentColumn])
        {
            userActivities1.push_back({activity.row, activity.column, activity.cost + 1});
            userActivities1.push_back({activity.row + 1, activity.column, activity.cost + 1});
            userActivities2.push_back({activity.row, activity.column, activity.cost + 1});
            userActivities2.push_back({activity.row, activity.column + 1, activity.cost + 1});
        }
        else if (activity.column > 0 && userActivities[activity.row][currentColumn] != desiredActivities[activity.row][currentColumn] && 
            userActivities[activity.row][currentColumn - 1] != desiredActivities[activity.row][currentColumn - 1])
        {
            userActivities1.push_back({activity.row, activity.column - 1, activity.cost + 1});
            userActivities1.push_back({activity.row, activity.column, activity.cost + 1});
            userActivities2.push_back({activity.row, activity.column, activity.cost + 1});
            userActivities2.push_back({activity.row, activity.column + 1, activity.cost + 1});
        }
        else
            userActivities1.push_back(activity), userActivities2.push_back(activity);
    }

    sort(userActivities1.begin(), userActivities1.end());
    sort(userActivities2.begin(), userActivities2.end());
    minimumCost = min(minimumCost, calculateOptimalCost(currentColumn + 1, userActivities1));
    minimumCost = min(minimumCost, calculateOptimalCost(currentColumn + 1, userActivities2));
    return minimumCost;
}

