class MaxFlow {
public:
    struct Edge {
        int to, cap, rev; // Define an edge with destination, capacity, and reverse edge
    };
    vector<vector<Edge>> graph; // Declare a vector of vectors to represent the residual graph
    vector<bool> visited; // Declare a vector of booleans to keep track of visited nodes
    int nodes, source, sink; // Declare variables for the number of nodes, source node, and sink node

    MaxFlow(int numNodes, int src, int snk) { // Constructor for MaxFlow
        nodes = numNodes;
        source = src;
        sink = snk;
        graph.resize(nodes); // Resize the residual graph to the specified number of nodes
        visited.resize(nodes); // Resize the visited vector to the specified number of nodes
    }

    void addEdge(int from, int to, int capacity) { // Function to add an edge to the residual graph
        Edge e1 = {to, capacity, (int)graph[to].size()}; // Create the forward edge
        Edge e2 = {from, 0, (int)graph[from].size()}; // Create the reverse edge
        graph[from].push_back(e1); // Add the forward edge to the graph
        graph[to].push_back(e2); // Add the reverse edge to the graph
    }

    bool findPath(int current, int destination) { // Function to find an augmenting path using DFS
        if (current == destination) return true; // Base case: if the current node is the destination, return true
        visited[current] = true; // Mark the current node as visited
        for (Edge &e : graph[current]) { // Iterate over all the edges from the current node
            if (!visited[e.to] && e.cap > 0) { // If the destination node is not visited and the edge has capacity
                if (findPath(e.to, destination)) { // Recursively find a path from the destination node
                    return true; // If a path is found, return true
                }
            }
        }
        return false; // If no path is found, return false
    }

    int augmentFlow(int current, int destination, int &minCap, int capacity) { // Function to augment the flow along the augmenting path
        if (current == destination) { // Base case: if the current node is the destination, return the minimum capacity
            minCap = capacity;
            return capacity;
        }
        visited[current] = true; // Mark the current node as visited
        for (Edge &e : graph[current]) { // Iterate over all the edges from the current node
            if (!visited[e.to] && e.cap > 0) { // If the destination node is not visited and the edge has capacity
                int f = augmentFlow(e.to, destination, minCap, min(capacity, e.cap)); // Recursively augment the flow along the path
                if (f > 0) { // If a flow can be augmented
                    e.cap -= f; // Update the capacity of the forward edge
                    graph[e.to][e.rev].cap += f; // Update the capacity of the reverse edge
                    return f; // Return the augmented flow
                }
            }
        }
        return 0; // If no flow can be augmented, return 0
    }

    int maxFlow() { // Function to find the maximum flow using Edmonds-Karp algorithm
        int flow = 0; // Initialize the flow to 0
        while (findPath(source, sink)) { // While an augmenting path exists
            visited.assign(nodes, false); // Reset the visited vector
            int minCap = INT_MAX; // Initialize the minimum capacity to infinity
            int f = augmentFlow(source, sink, minCap, INT_MAX); // Augment the flow along the augmenting path
            while (f > 0) { // While the flow can be augmented
                flow += f; // Add the augmented flow to the total flow
                f = augmentFlow(source, sink, minCap, INT_MAX); // Augment the flow along the augmenting path
            }
        }
        return flow; // Return the maximum flow
    }

    int minCut() { // Function to return the minimum cut through the graph
        int flow = 0; // Initialize the flow to 0
        for (Edge &e : graph[source]) { // Iterate over all the edges from the source node
            flow += e.cap; // Add the capacity of each edge to the flow
        }
        return flow; // Return the minimum cut through the graph
    }
};

int main() { // Main function to solve the problem
    freopen("input.txt", "r", stdin); // Open the input file
    freopen("output.txt", "w", stdout); // Open the output file
    int t; // Declare a variable to read the number of test cases
    cin >> t; // Read the number of test cases
    while (t--) { // For each test case
        cin >> n >> m >> k; // Read the number of nodes, edges, and queries
        for (int i = 0; i < n; i++) { // Initialize the graph
            for (int j = 0; j < n; j++) {
                g[i][j] = INT_MAX; // Set all distances to infinity
            }
        }
        for (int i = 0; i < m; i++) { // Read the edges of the graph
            int u, v, w;
            cin >> u >> v >> w;
            u--, v--; // Convert 1-based indices to 0-based indices
            g[u][v] = g[v][u] = min(g[u][v], w); // Update the graph with the weight of the edge
            edge[i] = make_pair(u, v); // Store the edge in the edge array
        }
        for (int k = 0; k < n; k++) { // Compute all-pairs shortest paths using Floyd-Warshall algorithm
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    g[i][j] = min(g[i][j], g[i][k] + g[k][j]); // Update the distance between nodes i and j
                }
            }
        }
        MaxFlow mf(n + 2, n, n + 1); // Create a MaxFlow object with n + 2 nodes, n as the source, and n + 1 as the sink
        for (int i = 0; i < m; i++) { // Add edges to the residual graph
            int u = edge[i].first;
            int v = edge[i].second;
            if (g[n][u] + 1 + g[v][n + 1] == g[n][n + 1]) { // If the edge is on the shortest path from the source to the sink
                mf.addEdge(u, v, 1); // Add a forward edge with capacity 1
                mf.addEdge(v, u, 1); // Add a reverse edge with capacity 1
            }
        }
        int maxflow = mf.maxFlow(); // Find the maximum flow using the MaxFlow algorithm
        if (k > 0) { // If there are queries
            for (int i = 0; i < k; i++) { // For each query
                int u = edge[i].first;
                int v = edge[i].second;
                mf.addEdge(u, v, 1); // Add the query edge with capacity 1
                mf.addEdge(v, u, 1); // Add the reverse edge with capacity 1
                maxflow = max(maxflow, mf.maxFlow()); // Find the maximum flow after adding the query edge
            }
        }
        cout << maxflow << endl; // Print the maximum flow for the current test case
    }
    return 0; // Exit the program
}

