  int rides = 0, promised = 0;
  multiset<pair<int, int>> Q;
  for (int i = 1; i <= n; i++) {
    Q.insert({prime[i], beauty[i]});
  }
  vector<pair<int, int>> toRemove;
  for (auto it = Q.begin(); it != Q.end(); it++) {
    if (!visited[it->first]) {
      rides++;
      visited[it->first] = true;
      toRemove.push_back(*it);
    }
  }
  for (auto it : toRemove) {
    Q.erase(it);
  }
  for (int i = 1; i <= s; i++) {
    counters[i].clear();
  }
  for (int i = 1; i <= n; i++) {
    counters[prime[i]].insert(beauty[i]);
  }
  for (int i = 1; i <= s; i++) {
    if (counters[i].size() > rides) {
      promised += counters[i].size() - rides;
    }
  }
  return {rides, promised};
