int calculate_best_path(char starting_node, char original_node, char destination_node, bool visited_destination) {
  if (visited_path[original_node][destination_node] && visited_path[destination_node][original_node]) {
    return 0;
  }
  if (!visited_destination) {
    return edge_costs[destination_node] + calculate_best_path(!starting_node, original_node, original_node, true);
  }
  if (visited_destination) {
    return edge_costs[original_node] + calculate_best_path(!starting_node, original_node, destination_node, true);
  }
  int best_score = numeric_limits<int>::min();
  for (const auto &[next_node, _] : adjacency_list[original_node]) {
    if (next_node != parent_nodes[original_node]) {
      best_score = max(best_score, edge_costs[original_node] + calculate_best_path(starting_node, original_node, next_node, visited_destination));
    }
  }
  for (const auto &[next_node, _] : adjacency_list[destination_node]) {
    if (next_node != parent_nodes[destination_node]) {
      best_score = max(best_score, edge_costs[destination_node] + calculate_best_path(starting_node, original_node, next_node, visited_destination));
    }
  }
  return best_score;
