    if (r - 1 >= 0 && grid[getIdx(r - 1, c)] > 0)
        merge(u, getIdx(r - 1, c), par, sz);
    if (r + 1 < s && grid[getIdx(r + 1, c)] > 0)
        merge(u, getIdx(r + 1, c), par, sz);
    if (c - 1 >= 0 && grid[getIdx(r, c - 1)] > 0)
        merge(u, getIdx(r, c - 1), par, sz);
    if (c + 1 < m && grid[getIdx(r, c + 1)] > 0)
        merge(u, getIdx(r, c + 1), par, sz);
}

bool bridge(int *grid) {
    for (int i = 0; i < s; i++) {
        for (int j = 0; j < m; j++) {
            if (grid[getIdx(i, j)] == 2) {
                int cnt = 0;
                if (i - 1 >= 0 && grid[getIdx(i - 1, j)] > 0)
                    cnt++;
                if (i + 1 < s && grid[getIdx(i + 1, j)] > 0)
                    cnt++;
                if (j - 1 >= 0 && grid[getIdx(i, j - 1)] > 0)
                    cnt++;
                if (j + 1 < m && grid[getIdx(i, j + 1)] > 0)
                    cnt++;
                if (cnt == 2)
                    return true;
            }
        }
    }
    return false;
}

bool fork(int *grid) {
    for (int i = 0; i < s; i++) {
        for (int j = 0; j < m; j++) {
            if (grid[getIdx(i, j)] == 2) {
                int cnt = 0;
                if (i - 1 >= 0 && grid[getIdx(i - 1, j)] > 0)
                    cnt++;
                if (i + 1 < s && grid[getIdx(i + 1, j)] > 0)
                    cnt++;
                if (j - 1 >= 0 && grid[getIdx(i, j - 1)] > 0)
                    cnt++;
                if (j + 1 < m && grid[getIdx(i, j + 1)] > 0)
                    cnt++;
                if (cnt >= 3)
                    return true;
            }
        }
    }
    return false;
}

int dfs(int r, int c, int *grid, int *par) {
    int u = getIdx(r, c);
    if (grid[u] == 0)
        return 0;
    if (par[u] != -1)
        return par[u];
    int cnt = 1;
    if (r - 1 >= 0 && grid[getIdx(r - 1, c)] > 0)
        cnt += dfs(r - 1, c, grid, par);
    if (r + 1 < s && grid[getIdx(r + 1, c)] > 0)
        cnt += dfs(r + 1, c, grid, par);
    if (c - 1 >= 0 && grid[getIdx(r, c - 1)] > 0)
        cnt += dfs(r, c - 1, grid, par);
    if (c + 1 < m && grid[getIdx(r, c + 1)] > 0)
        cnt += dfs(r, c + 1, grid, par);
    return par[u] = cnt;
}

bool ring(int *grid) {
    int par[N * N];
    memset(par, -1, sizeof par);
    for (int i = 0; i < s; i++) {
        for (int j = 0; j < m; j++) {
            if (grid[getIdx(i, j)] > 0) {
                if (par[getIdx(i, j)] == -1) {
                    int cnt = dfs(i, j, grid, par);
                    if (cnt >= 4)
                        return true;
                }
            }
        }
    }
    return false;
}

void solve() {
    int s, m;
    read(s, m);
    int grid[N * N];
    memset(grid, 0, sizeof grid);
    int par[N * N];
    memset(par, -1, sizeof par);
    int sz[N * N];
    for (int i = 0; i < s; i++) {
        for (int j = 0; j < m; j++) {
            int x;
            cin >> x;
            if (x)
                add(i, j, grid, par, sz);
        }
    }
    if (bridge(grid))
        cout << "bridge " << x << endl;
    else if (fork(grid))
        cout << "fork " << x << endl;
    else if (ring(grid))
        cout << "ring " << x << endl;
    else
        cout << "none" << endl;
}

