const int N = 1000005, md = 1000000007;
int n, k, f[N], s[N];

inline void add(int &a, int b) { a = (a + b) % md; }
inline void sub(int &a, int b) { a = (a - b + md) % md; }
inline int mul(int a, int b) { return (1LL * a * b) % md; }
inline int power(int a, int b) {
  int ans = 1;
  while (b) {
    if (b % 2) ans = mul(ans, a);
    a = mul(a, a);
    b /= 2;
  }
  return ans;
}
inline int inv(int x) { return power(x, md - 2); }

int main() {
