            circles[j].circleSurfaceArea = pi * circles[j].radius * circles[j].radius;
        }

        sort(circles.begin(), circles.end(), compareCircles);

        priority_queue<double> pq;
        double maxArea = 0;

        for (int j = 0; j < numCircles; j++) {
