void Trim(State &s) {
    for (int i = 0; i < k; ++i) {
        for (int j = i + 1; j < k; ++j) {
            if (s.pi[i] > s.pi[j]) {
                swap(s.pi[i], s.pi[j]), swap(s.pj[i], s.pj[j]);
            } else if (s.pi[i] == s.pi[j]) {
