const int INFINITY = 1e9;
const int MAX_SIZE = 1e5;
int total_items, total_orders;
vector<int> reserve_levels, quantities[MAX_SIZE][MAX_SIZE], excess_quantities[MAX_SIZE][MAX_SIZE][2];
int lower_bounds[MAX_SIZE], upper_bounds[MAX_SIZE];

struct ResourceConnection {
    int destination, capacity, reverse_connection_index;
};

class ResourceAllocator {
    vector<vector<ResourceConnection>> connections;
    vector<int> queue, level;

public:
    ResourceAllocator(int size) : connections(size) {}

    void connect(int source, int destination, int capacity) {
        connections[source].push_back({destination, capacity, (int)connections[destination].size()});
        connections[destination].push_back({source, 0, (int)connections[source].size() - 1});
    }

    bool find_path(int source, int destination, int max_capacity) {
        if (source == destination) return true;
        level[source] = 1;
        queue.push_back(source);
        for (ResourceConnection& connection : connections[source]) {
            if (connection.capacity > 0 && level[connection.destination] == 0 && find_path(connection.destination, destination, min(max_capacity, connection.capacity))) {
                connection.capacity -= max_capacity;
                connections[connection.destination][connection.reverse_connection_index].capacity += max_capacity;
                return true;
            }
        }
        return false;
    }

    int allocate_maximum_resources(int source, int destination) {
        int total_allocated = 0;
        while (true) {
            queue.clear();
            level.assign(connections.size(), 0);
            if (!find_path(source, destination, INFINITY)) break;
            while (!queue.empty()) {
                int current_node = queue.back();
                queue.pop_back();
                for (ResourceConnection& connection : connections[current_node]) {
                    if (connection.capacity > 0 && level[current_node] > 0 && level[current_node] + 1 == level[connection.destination]) {
                        if (find_path(connection.destination, destination, min(connection.capacity, max_capacity))) {
                            connection.capacity -= max_capacity;
                            connections[connection.destination][connection.reverse_connection_index].capacity += max_capacity;
                            total_allocated += max_capacity;
                        }
                    }
                }
            }
        }
        return total_allocated;
    }
};

void solve() {
    cin >> total_items >> total_orders >> lower_bounds[0];
    int input;
    for (int i = 1; i <= total_items; i++) {
        cin >> input;
        reserve_levels.push_back(input);
        cin >> upper_bounds[i] >> lower_bounds[i];
    }
    for (int j = 0; j < total_orders; j++) {
        for (int i = 0; i < total_items; i++) {
            cin >> quantities[i][j];
            excess_quantities[i][j][0] = (quantities[i][j] > lower_bounds[i]) ? quantities[i][j] - lower_bounds[i] : 0;
            excess_quantities[i][j][1] = (quantities[i][j] > upper_bounds[i]) ? upper_bounds[i] - lower_bounds[i] : quantities[i][j] - lower_bounds[i];
        }
    }

    ResourceAllocator allocator(total_items + total_orders + 2);
    int source = total_items + total_orders, destination = total_items + total_orders + 1;
    for (int i = 0; i < total_items; i++) {
        allocator.connect(source, i, reserve_levels[i]);
        for (int j = 0; j < total_orders; j++) {
            allocator.connect(i, total_items + j, excess_quantities[i][j][1]);
        }
    }
    for (int j = 0; j < total_orders; j++) {
        allocator.connect(total_items + j, destination, INFINITY);
    }
    cout << allocator.allocate_maximum_resources(source, destination) << endl;
}

int main() {
    int test_cases;
    cin >> test_cases;
    while (test_cases--) solve();
}

