  g.resize(f.size());
  g[f.size()-1] = inv(f[f.size()-1]);
  for (int i = f.size()-2; i >= 0; i--) g[i] = (1LL * g[i+1] * (i+1)) % MOD;
}

int inv(int a) {
  int b = MOD, u = 0, v = 1;
  while (b) {
    int t = a / b;
    a -= t * b; swap(a, b);
    u -= t * v; swap(u, v);
  }
  return (u + MOD) % MOD;
}

void calculateFact() {
  int limit = getInput() + 1;
  fact.resize(limit);
  inv_fact.resize(fact.size());
  fact[0] = 1;
  for (int i = 1; i < fact.size(); i++) fact[i] = (1LL * fact[i-1] * i) % MOD;
  inv_fact[fact.size()-1] = inv(fact[fact.size()-1]);
  for (int i = fact.size()-2; i >= 0; i--) inv_fact[i] = (1LL * inv_fact[i+1] * (i+1)) % MOD;
}

int acomb(int n, int x) {
  if (x < 0 || x > n) return 0;
  return (1LL * fact[n] * inv_fact[n-x]) % MOD;
}

int main(int argc, char** argv) {
  calculateFg();
  calculateFact();
  cout << "The result is:" << acomb(f.size()-1, getInput()) << endl;
  return 0;
}
