int n, m, counter, space[57][57], board[57][57];
set<pair<int, int>> explored;
bool valid = true;
int direction[4] = {0, 0, 1, -1}, movement[4] = {1, -1, 0, 0};
bool withinBounds(int x, int y) { return x >= 1 && x <= n && y >= 1 && y <= m; }
void explore(int x, int y, int orientation) {
  if (!withinBounds(x, y)) return;
  if (board[x][y] != -1) return;
  explored.insert({x, y});
  if (space[x][y] == '-' && (orientation == 2 || orientation == 3)) valid = false;
  if (space[x][y] == '|' && (orientation == 0 || orientation == 1)) valid = false;
  board[x][y] = counter;
  for (int i = 0; i < 4; i++) {
    int nextX = x + direction[i], nextY = y + movement[i];
    if (withinBounds(nextX, nextY) && space[nextX][nextY] != '.') explore(nextX, nextY, i);
  }
}
vector<int> dependency[57], dependent[57];
int order[57], position[57];
void topologicalSort(int vertex) {
  for (auto u : dependency[vertex]) if (!order[u]) topologicalSort(u);
  order[vertex] = counter++;
}
void assignColor(int vertex, int color) {
  board[position[vertex][0]][position[vertex][1]] = color;
  for (auto u : dependent[vertex])
    if (board[position[u][0]][position[u][1]] == -1) assignColor(u, color);
}
