  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= m; j++) {
      char input;
      cin >> input;
      space[i][j] = input;
      if (input == '.' || input == '-') board[i][j] = -1;
    }
  }
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= m; j++) {
      if (board[i][j] == -1) {
        explore(i, j, -1);
        if (!valid) return cout << "IMPOSSIBLE", 0;
        counter++;
        explored.clear();
        valid = true;
      }
    }
  }
  for (int i = 1; i < counter; i++) {
    for (int j = i + 1; j < counter; j++) {
      auto it = explored.find({i, j});
      if (it == explored.end()) {
        dependency[i].push_back(j);
        dependent[j].push_back(i);
      }
    }
  }
  for (int i = 1; i < counter; i++)
    if (!order[i]) topologicalSort(i);
  counter = 0;
  for (int i = counter - 1; i >= 1; i--) {
    int vertex = 0;
    for (int j = 1; j < counter; j++)
      if (order[j] == i) vertex = j;
    assignColor(vertex, counter);
    counter++;
  }
  for (int i = 1; i <= n; i++) {
