vector<int> s(int n, int A, vector<vector<int>> g, vector<int>oI, vector<vector<int>> &oG, int wIH) // adjacency matrix
{
    vector<int> a;
    bool cC = false;
    if (n == 1) {

        if (wIH == -1 || oG[wIH][oI[0]]) {
            wIH = oI[0];
        }
        if (wIH == rA){
            a.push_back(0);
        }
        return a;
    }
    else
    {
        ++vCnt;


        e.clear();
        for (int i = 0; i < n; i++) {
            if (v[i] == vCnt) continue;
            dfs(g, i, false);
        }

        ++vCnt;
        vector<int> fg;
        vector<int> q(e.rbegin(), e.rend());

        bool nR = false;
        if (A == -1) {
            nR = true;
        }
        for (auto start : q) {
            if (v[start] == vCnt) continue;
            e.clear();
            dfs(g, start, true);
            if (fg.empty()) {
                fg = e;
            }

            if (nR){
                bool f = false;
                if (wIH == -1) {
                    f = true;
                }
                else {
                    for (auto e : e) {
                        if (!oG[oI[e]][wIH])
                        {
                            f = true;
                            break;
                        }
                    }
                }
                if (f) return a;
            }
            else {
                if (wIH == -1) {
                    cC = true;
                }
                else {
                    for (auto e : e) {
                        if (oG[wIH][oI[e]])
                        {
                            cC = true;
                            break;
                        }
                    }
                }
            }

            if (find(e.begin(), e.end(), A) == e.end()) {
                // not found
            }
            else {
                nR = true;
            }
        }

        if (A == -1){
            for (int i = 0; i < n; i++) {
                a.push_back(i);
            }
            return a;
        }

        if (cC)
        {
            for (int pathStart = 0; pathStart < n; pathStart++) {
                vector<vector<int>> ng(n-1, vector<int>(n-1));
                for (int i = 0; i < n; i++)
                {
                    if (i == pathStart) continue;
                    for (int j = 0; j < n; j++) {
                        if (j == pathStart) continue;
                        ng[i - (i >= pathStart)][j - (j >= pathStart)] = g[i][j];
                    }
                }
                vector<int> ns;
                for (int i = 0; i < n-1; i++) {
                    ns.push_back(oI[i + (i >= pathStart)]);
                }

                if (pathStart == A)
                {
                    if (wIH == -1 || oG[wIH][oI[pathStart]])
                    {
                        auto sub = s(n - 1, -1, ng, ns, oG, oI[pathStart]);
                        if (sub.empty()) continue;

                        a.push_back(pathStart);
                        for (auto s : sub) {
                            a.push_back(s + (s >= pathStart));
                        }
                        break;
                    }
                }
                else
                {
                    if (wIH == -1 || oG[wIH][oI[pathStart]])
                    {
                        // changes
                        auto sub = s(n - 1, A - (A >= pathStart), ng, ns, oG, oI[pathStart]);
                        if (sub.empty()) continue;

                        a.push_back(pathStart);
                        for (auto s : sub) {
                            a.push_back(s + (s >= pathStart));
                        }
                        break;
                    }
                    else
                    {
                        // remains
                        auto sub = s(n - 1, A - (A >= pathStart), ng, ns, oG, wIH);
                        if (sub.empty()) continue;

                        a.push_back(pathStart);
                        for (auto s : sub) {
                            a.push_back(s + (s >= pathStart));
                        }
                        break;
                    }
                }
            }
        }
    }

    if (cC && a.empty())
    {
        a = a;
    }
    return a;
}

