#include <iostream>
#include <vector>
#include <stack>

using namespace std;

const int MAXN = 100000;
vector<int> adj[MAXN];
vector<int> adjinv[MAXN];
vector<int> scc[MAXN];
int vis[MAXN];
int low[MAXN];
int num[MAXN];
int sccs;
stack<int> st;
int dfsTime;

void tarjan(int u) {
  low[u] = num[u] = dfsTime++;
  st.push(u);
  vis[u] = 1;
  for (int v : adj[u]) {
    if (!vis[v]) {
      tarjan(v);
      low[u] = min(low[u], low[v]);
    } else if (vis[v] == 1) {
      low[u] = min(low[u], num[v]);
    }
  }
  if (low[u] == num[u]) {
    int v;
    do {
      v = st.top();
      st.pop();
      scc[sccs].push_back(v);
      vis[v] = 2;
    } while (v != u);
    sccs++;
  }
}

int dfs(int u, int prohibited) {
  int ans = 0;
  vis[u] = 1;
  for (int v : adj[u]) {
    if (!vis[v] && v != prohibited) {
      ans = max(ans, 1 + dfs(v, prohibited));
    }
  }
  return ans;
}

int main() {
  int n, m;
  cin >> n >> m;
  for (int i = 0; i < m; i++) {
    int u, v;
    cin >> u >> v;
    adj[u].push_back(v);
    adjinv[v].push_back(u);
  }
  for (int i = 1; i <= n; i++) {
    if (!vis[i]) {
      tarjan(i);
    }
  }
  int ans = 0;
  for (int i = 0; i < sccs; i++) {
    for (int u : scc[i]) {
      for (int v : adjinv[u]) {
        int prohibited = u;
        if (vis[v] == 2) {
          int path = dfs(v, prohibited);
          ans = max(ans, path + 1);
        }
      }
    }
  }
  cout << ans << endl;
  return 0;
}

