// Class
class BigInteger {
private:
  vector<int> digits;

public:
  BigInteger(int x = 0) {
    while (x > 0) {
      digits.push_back(x % 10);
      x /= 10;
    }
  }

  BigInteger operator+(const BigInteger &other) const {
    BigInteger sum;
    int carry = 0;
    for (int i = 0; i < max(digits.size(), other.digits.size()); i++) {
      int digit1 = i < digits.size() ? digits[i] : 0;
      int digit2 = i < other.digits.size() ? other.digits[i] : 0;
      int result = digit1 + digit2 + carry;
      sum.digits.push_back(result % 10);
      carry = result / 10;
    }
    if (carry > 0) sum.digits.push_back(carry);
    return sum;
  }

  BigInteger operator-(const BigInteger &other) const {
    BigInteger difference;
    int carry = 0;
    for (int i = 0; i < max(digits.size(), other.digits.size()); i++) {
      int digit1 = i < digits.size() ? digits[i] : 0;
      int digit2 = i < other.digits.size() ? other.digits[i] : 0;
      int result = digit1 - digit2 - carry;
      if (result < 0) {
        result += 10;
        carry = 1;
      } else
        carry = 0;
      difference.digits.push_back(result);
    }
    while (difference.digits.size() > 1 && difference.digits.back() == 0)
      difference.digits.pop_back();
    return difference;
  }

  BigInteger operator*(const int64_t &multiplier) const {
    BigInteger product;
    int64_t carry = 0;
    for (int i = 0; i < digits.size(); i++) {
      int64_t multiplication = static_cast<int64_t>(digits[i]) * multiplier + carry;
      product.digits.push_back(multiplication % 10);
      carry = multiplication / 10;
    }
    if (carry > 0) product.digits.push_back(carry);
    return product;
  }

  BigInteger operator/(const int64_t &divisor) const {
    BigInteger quotient;
    int64_t remainder = 0;
    for (int i = digits.size() - 1; i >= 0; i--) {
      int64_t division = remainder * 10 + digits[i];
      quotient.digits.push_back(division / divisor);
      remainder = division % divisor;
    }
    while (quotient.digits.size() > 1 && quotient.digits.back() == 0)
      quotient.digits.pop_back();
    reverse(quotient.digits.begin(), quotient.digits.end());
    return quotient;
  }

  BigInteger operator%(const int64_t &divisor) const {
    BigInteger remainder = *this;
    return remainder /= divisor;
  }

  bool operator<(const BigInteger &other) const {
    if (digits.size() != other.digits.size())
      return digits.size() < other.digits.size();
    for (int i = digits.size() - 1; i >= 0; i--) {
      if (digits[i] != other.digits[i]) return digits[i] < other.digits[i];
    }
    return false;
  }
};

