int explore(vector<int> &besties, vector<bool> &visited, int n, int source, int start, int predecessor) {
    if (!visited[besties[source]]) {
        visited[source] = true;
        visited[besties[source]] = true;
        predecessors[source] = predecessor;
        return explore(besties, visited, n, besties[source], start, source);
    } else if (predecessor == besties[source]) {
        visited[source] = true;
        int count = 0;
        for (int i = 0; i < n; i++) {
            if (!visited[i]) count = max(count, explore(besties, visited, n, i, start, source));
        }
        return count;
    } else {
        return explore(besties, visited, n, besties[source], start, source);
    }
}

