int rows, columns, grid[MAX_SIZE][MAX_SIZE], row_offsets[] = {1, 0, -1, 0}, column_offsets[] = {0, 1, 0, -1}, counts[MAX_SIZE][MAX_SIZE];

bool is_within_bounds(int row, int column) { return row >= 0 && row < rows && column >= 0 && column < columns; }

void read_input() { cin >> rows >> columns; }

void process_input() {
  for (int column = 0; column < columns; column++) grid[0][column] = (column & 1);
  for (int row = 1; row < rows; row++) {
    for (int column = 0; column < columns; column++) {
      for (int direction = 0; direction < 4; direction++) {
        int neighboring_row = row + row_offsets[direction], neighboring_column = column + column_offsets[direction];
        if (is_within_bounds(neighboring_row, neighboring_column)) counts[row][column] += (grid[row][column] == grid[neighboring_row][neighboring_column]);
      }
      grid[row][column] ^= (counts[row][column] != grid[row][column]);
    }
  }
  bool is_valid = true;
  for (int column = 0; column < columns; column++) is_valid &= (counts[rows - 1][column] == grid[rows - 1][column]);
  if (is_valid) cout << "YES\n";
  else
    cout << "NO\n";
}

int main() {
