bool forever(const vector<vector<int>>& board) {
    int cnta = 0, cntb = 0;
    for (int i = 0; i < medir; i++) {
        for (int j = 0; j < medjc; j++) {
            if (board[i][j] == 1) cnta++;
            if (board[i][j] == 2) cntb++;
        }
    }
    if (cnta > 0 && cntb > 0) return true;
    return false;
}

bool underthreat(const vector<vector<int>>& board) {
    for (int i = 0; i < medir; i++) {
        for (int j = 0; j < medjc; j++) {
            if (board[i][j] > 0) {
                for (int k = 0; k < 4; k++) {
                    int nr = i + dr[k];
                    int nc = j + dc[k];
                    if (nr >= 0 && nr < medir && nc >= 0 && nc < medjc && board[nr][nc] > 0 && board[nr][nc] != board[i][j]) {
                        return true;
                    }
                }
            }
        }
    }
    return false;
}

