double bscore(int idx, double dist, int prv) {
  if (idx == su) return 0;
  if (dist > R) return -1e9;
  double &ret = stable[idx][prv];
  if (ret != -1) return ret;
  ret = bscore(idx, dist + abs(p[idx] - p[prv]), idx) + 1;
  for (int i = 0; i < N; i++) {
    if (i == prv || i == su) continue;
    ret = max(ret, bscore(idx, dist + abs(p[idx] - p[i]), prv) + 1);
  }
  return ret;
}
