    inputFile >> cells >> rows >> columns;
    testCases.push(std::make_tuple(cells, rows, columns));
  }
}

void solveAndOutput(std::ofstream& outputFile, int numberOfTests, std::queue<std::tuple<int, int, int>>& testCases) {
  for (int i = 0; i < numberOfTests; i++) {
    int cells, rows, columns;
    std::tie(cells, rows, columns) = testCases.front();
    testCases.pop();

    int partitions = (cells - rows + 1) * (cells - columns + 1);
    outputFile << partitions << std::endl;
  }
}

// Main Function
