    }
    sum += *min_element(quality.begin(), quality.end());
    int smallest = min_element(quality.begin(), quality.end()) - quality.begin();
    for (int i = 0; i < projects; i++) {
      for (int mask = 0; mask < (1 << projects - 1); mask++) {
        if ((smallest >> i) & 1) swap(matrix[i][mask], matrix[i][mask ^ (1 << i)]);
      }
    }
    matrix.erase(matrix.begin() + smallest);
    quality.erase(quality.begin() + smallest);
  }
  return sum;
