bool Valid(int row) {
    for (int i = 0; i < constraints; i++) {
        if (taken[row][i]) return false;
    }
    return true;
}

void Activate(int row) {
    for (int i = 0; i < constraints; i++) {
        if (row & (1 << i)) taken[row][i] = true;
    }
}

void Deactivate(int row) {
    for (int i = 0; i < constraints; i++) {
        if (row & (1 << i)) taken[row][i] = false;
    }
}

void Find(int stage) {
    if (stage == constraints) {
        if (result == solution) problems++;
        return;
    }
    for (int i = stage + 1; i < constraints; i++) {
        if (Valid(1 << i)) {
            result += originalValues[i];
            Activate(1 << i);
            Find(i + 1);
            Deactivate(1 << i);
            result -= originalValues[i];
        }
    }
}

void Input() {
    cin >> solution >> constraints;
    problems = 0;
    for (int i = 1; i < constraints; i++) cin >> originalValues[i];
    result = 0;
    Find(0);
    cout << problems << endl;
}

