### Game Variables:
number of rounds: n;

### Actions:
function to generate a sequence of actions starting with a given action (action): gen(action) {
  create a sequence of actions result that is the same as the  input action;
  for each round from 1 to n, in sequence: {
    for each action in the result sequence: {
      if the action is 'S', change it to 'P';
      if the action is 'P', change it to 'R';
      if the action is 'R', change it to 'S';
    }
    update the result sequence with the modified actions;
  }
  return the result sequence;
}

function to check if a sequence of actions is possible (sequence, r, p, s): {
  for each action in the sequence: {
    if the action is 'S' and the number of scissors is 0, return false;
    if the action is 'P' and the number of papers is 0, return false;
    if the action is 'R' and the number of rocks is 0, return false;
    if the action is 'S', decrease the number of scissors by 1;
    if the action is 'P', decrease the number of papers by 1;
    if the action is 'R', decrease the number of rocks by 1;
  }
  return true;
}

function to sort a sequence of actions (sequence, n): {
  if n is 1, return the sequence;
  divide the sequence into left and right halves;
  sort the left half recursively;
  sort the right half recursively;
  merge the sorted left and right halves into a new sequence result;
  return the result sequence;
}

### Main Game:
get the number of test cases: t;

for each test case: {
  get the number of rounds: n;
  get the number of scissors, papers, and rocks: r, p, s;
  generate three possible sequences of actions: r1 (starting with 'S'), r2 (starting with 'P'), r3 (starting with 'R');
  check if r1 is possible;
  if r1 is possible, sort it and print it;
  otherwise, check if r2 is possible;
  if r2 is possible, sort it and print it;
  otherwise, check if r3 is possible;
  if r3 is possible, sort it and print it;
  otherwise, print "IMPOSSIBLE";
}

