void exchange(int firstPtr, int secondPtr) {
  char temp = actualBuf[firstPtr];
  actualBuf[firstPtr] = actualBuf[secondPtr];
  actualBuf[secondPtr] = temp;
}

int compare(const void *firstPtr, const void *secondPtr) {
  return *(char *)secondPtr - *(char *)firstPtr;
}

void process() {
  bool modified = false;
  for (int i = 0; actualBuf[i]; i++) {
    if (actualBuf[i] < actualBuf[i + 1]) {
      exchange(i, i + 1);
      qsort(actualBuf, i + 1, sizeof(char), compare);
      modified = true;
      return;
    }
  }
  if (!modified) {
    for (int i = 1; actualBuf[i]; i++) {
      if (actualBuf[i] && actualBuf[i] != '0') {
        exchange(0, i);
        qsort(actualBuf, i + 1, sizeof(char), compare);
        return;
      }
    }
  }
}

