  if (DP.count(p) && DP[p].count(S)) return 1 - DP[p][S].first;
  bool ok;
  int dx, dy, ans = 1;
  for (dx = x - 1; dx <= x + 1; dx++) {
    for (dy = y - 1; dy <= y + 1; dy++) {
      if ((dx != x || dy != y) && make_move(n, m, dx, dy, ok)) { ans &= go(n, m, dx, dy, 1 - p); ok = 0; }
    }
  }
  return DP[p][S] = {ans, 0}, ans;
}

