void solve(int test_index) {
  int num_probs;     // Number of probabilities
  long double target;  // Target probability value
  cin >> num_probs >> target;
  vector<long double> probabilities(num_probs);
  long double sum = 0.0;   // Sum of probabilities
  long double product = 1.0;  // Product of probabilities
  for (int i = 0; i < num_probs; ++i) {
    cin >> probabilities[i];
    sum += probabilities[i];
    product *= probabilities[i];
  }
  sort(probabilities.rbegin(), probabilities.rend());
  long double current_sum = 0.0;
  long double best_result = product;
  for (int i = 0; i <= num_probs; ++i) {
    if (i > 0) { current_sum += probabilities[i - 1]; }
    long double to_distribute = i - current_sum;
    if (to_distribute > target + eps) { continue; }
    long double remaining = target - to_distribute;
    if (i < num_probs) {
      long double each_portion = remaining / (num_probs - i);
      if (probabilities[i] > each_portion + eps) { continue; }
      long double result = 1.0;
      for (int j = 0; j < num_probs - i; ++j) { result *= each_portion; }
      best_result = max(best_result, result);
    } else {
      best_result = 1.0;
    }
  }
  cout << "Case #" << test_index << ": " << fixed << setprecision(9) << best_result
       << endl;
}

