int totalTestCases, numOfRows, numOfCols;
int grid[COLS][ROWS], visited[COLS][ROWS];
int totalMatchingPairs;
int halfwayCount;

bool isWithinBounds(int x, int y) {
  return (x >= 0 && x < numOfRows && y >= 0 && y < numOfCols);
}

bool isValid(int x, int y) {
  int totalMatching = 0;
  for (int i = x - 1; i <= x + 1; i++) {
    for (int j = y - 1; j <= y + 1; j++) {
      if (isWithinBounds(i, j)) totalMatching += visited[i][j];
    }
  }
  return totalMatching == grid[x][y];
}

void backtrack(int x, int y) {
  if (x == numOfRows / 2) {
    if (halfwayCount > totalMatchingPairs) return;
    halfwayCount += (visited[x][y] == 1);
    if (halfwayCount > totalMatchingPairs) {
      totalMatchingPairs = halfwayCount;
      memcpy(visited, visited, sizeof(visited));
    }
    halfwayCount -= (visited[x][y] == 1);
    return;
  }
  for (int i = 0; i <= 1; i++) {
    visited[x][y] = i;
    if (isValid(x, y)) backtrack(x + 1, y);
  }
}

int main() {
  cin >> totalTestCases;
  while (totalTestCases--) {
    cin >> numOfRows >> numOfCols;
    for (int i = 0; i < numOfRows; i++) {
      for (int j = 0; j < numOfCols; j++) cin >> grid[i][j];
    }
    totalMatchingPairs = 0;
    halfwayCount = 0;
    backtrack(0, 0);
    cout << totalMatchingPairs << endl;
  }
  return 0;
}

