#include <bits/stdc++.h>
using namespace std;

struct node {
  int children[26], frequency, length;
} trie[1001];

int total = 0;
vector<node> dictionary;
unordered_map<int, int> paths;

int create_trie(const string& word) {
  int current = ++total;
  for (int i = 0; i < word.size(); ++i) {
    int character = word[i] - 'a';
    trie[current].children[character] = ++total;
    current = total;
  }
  trie[current].length = word.size();
  return dictionary.size(), dictionary.push_back(trie[current]);
}

void explore(int string_index, int service_index, int mask, int current_length) {
  if (string_index == dictionary.size()) {
    paths[mask] = max(paths[mask], current_length);
    return;
  }
  explore(string_index + 1, service_index, mask, current_length);
  if (trie[dictionary[string_index].children[trie[service_index].frequency]].length > 0) {
    mask |= (1 << string_index);
    explore(string_index + 1, service_index + 1, mask, current_length + trie[dictionary[string_index].children[trie[service_index].frequency]].length);
    mask ^= (1 << string_index);
  }
}

void solve() {
  int num_strings, num_services;
  cin >> num_strings >> num_services;
  for (int i = 0; i < num_strings; ++i) {
    string word;
    cin >> word;
    create_trie(word);
  }
  explore(0, 0, 0, 0);
  int best_count = 0, best_score = 0;
  for (auto& [mask, score] : paths) {
    if (score > best_count) {
      best_score = mask;
      best_count = score;
    }
  }
  cout << __builtin_popcount(best_score) << ' ' << best_count << '\n';
  dictionary.clear();
  total = 0;
  paths.clear();
}

