double calculateSegment(int *x, int *y, int index, double line) {
  double dx = x[1] - x[0];
  double dy = y[1] - y[0];
  return y[0] + dy / dx * (line - x[0]);
}
double calculateOffset(int lowerBound, int upperBound, double abscissa) {
  return calculateSegment(lowerX + lowerBound, lowerY + lowerBound, lowerBound, abscissa) - calculateSegment(upperX + upperBound, upperY + upperBound, upperBound, abscissa);
}
double findAbscissa(double currentArea, double targetArea) {
  double left = 0, right = figureWidth, middle;
  while (right - left > epsilon) {
    middle = (left + right) / 2;
    double enclosedArea = calculateOffset(0, upperLimit - 1, middle);
    enclosedArea -= calculateOffset(lowerBound, upperLimit - 1, middle);
    if (enclosedArea > targetArea) {
      left = middle + epsilon;
    } else if (enclosedArea < targetArea) {
      right = middle - epsilon;
    } else {
      return middle;
    }
  }
  return middle;
}
