double coefficientA(const double& area1, const double& area2, const double& theta, const double& tx, const double& ty) {
  return (area1 * cos(theta) + area2 * sin(theta) + tx * sin(theta) - ty * cos(theta)) / (area1 * sin(theta) - area2 * cos(theta) + tx * cos(theta) + ty * sin(theta));
}

double coefficientB(const double& area1, const double& area2, const double& theta, const double& tx, const double& ty) {
