#include <iostream>
#include <vector>
#include <queue>

using namespace std;

int nextValue() {
  int x;
  cout << "Enter an integer: ";
  cin >> x;
  return x;
}

int width, height;

bool isWithinBounds(int x, int lowerBound, int upperBound) {
  return lowerBound <= x && x <= upperBound;
}

vector<int> pointers;
vector<vector<map<int, int>>> flow, capacity, adjacentNodes;
vector<int> queue, distances;
int source, sink, numOfNodes;
const int MAX_VALUE = 1e9;

void breadthFirstSearch() {
  queue.clear();
  distances.assign(numOfNodes, MAX_VALUE);
  queue.push_back(source);
  distances[source] = 0;
  while (!queue.empty()) {
    int currentNode = queue.front();
    queue.erase(queue.begin());
    for (auto &adjacentNode : adjacentNodes[currentNode]) {
      int node = adjacentNode.first;
      if (distances[node] == MAX_VALUE && capacity[currentNode][node] > flow[currentNode][node]) {
        queue.push_back(node);
        distances[node] = distances[currentNode] + 1;
      }
    }
  }
}

int depthFirstSearch(int currentNode, int maxFlow) {
  if (currentNode == sink) return maxFlow;
  for (auto &pointer = pointers[currentNode]; pointer != adjacentNodes[currentNode].end(); ++pointer) {
    int node = pointer->first;
    if (distances[node] == distances[currentNode] + 1 && capacity[currentNode][node] > flow[currentNode][node]) {
      int flowThroughNode = depthFirstSearch(node, min(maxFlow, capacity[currentNode][node] - flow[currentNode][node]));
      if (flowThroughNode > 0) {
        flow[currentNode][node] += flowThroughNode;
        flow[node][currentNode] -= flowThroughNode;
        return flowThroughNode;
      }
    }
  }
  return 0;
}

int dinicAlgorithm() {
  int maxFlowValue = 0;
  while (true) {
    breadthFirstSearch();
    if (distances[sink] == MAX_VALUE) break;
    pointers.assign(numOfNodes, adjacentNodes[source].begin());
    while (int currentFlow = depthFirstSearch(source, MAX_VALUE)) maxFlowValue += currentFlow;
  }
  return maxFlowValue;
}

void solve() {
  width = nextValue(), height = nextValue();
  numOfNodes = width * height + 2;
  source = numOfNodes - 2, sink = numOfNodes - 1;
  flow.assign(numOfNodes, vector<map<int, int>>(numOfNodes));
  capacity.assign(numOfNodes, vector<map<int, int>>(numOfNodes));
  adjacentNodes.assign(numOfNodes, vector<pair<int, int>>());
  for (int row = 0; row < height; ++row) {
    for (int column = 0; column < width; ++column) {
      int value = nextValue();
      if (isWithinBounds(row, 0, height - 2)) {
        adjacentNodes[source].push_back({row * width + column + 1, value});
        capacity[source][row * width + column + 1] += value;
      }
      if (isWithinBounds(row, 1, height - 1)) {
        adjacentNodes[row * width + column + 1].push_back({source, 0});
        adjacentNodes[row * width + column + 1].push_back({row * width + column, value});
        adjacentNodes[row * width + column].push_back({row * width + column + 1, value});
        capacity[row * width + column + 1][source] += value;
        capacity[row * width + column + 1][row * width + column] += value;
        capacity[row * width + column][row * width + column + 1] += value;
      }
      if (isWithinBounds(row, 2, height - 1)) {
        adjacentNodes[row * width + column + 1].push_back({sink, value});
        capacity[row * width + column + 1][sink] += value;
      }
    }
  }
  cout << dinicAlgorithm() << endl;
}

int main() {
  solve();
  return 0;
}
