int tobase(int num, int base) {
  int result = 0;
  int power = 1;
  while (num > 0) {
    result += (num % base) * power;
    power *= 10;
    num /= base;
  }
  return result;
}

bool go(int num, int base, int lim) {
  vector<int> seen;
  for (int i = 0; i < lim; i++) {
    if (num == 1) {
      return true;
    }
    num = tobase(num * num, base);
    if (find(seen.begin(), seen.end(), num) != seen.end()) {
      return false;
    }
    seen.push_back(num);
  }
  return false;
}

