      son2[i].clear();
    }
    for (int i = 1; i < M; i++) {
      scanf("%d%d", &u, &v);
      next2[u].push_back(v);
      next2[v].push_back(u);
    }
    buildTree(1, M, next2, son2);
    memset(Ans, 0, sizeof Ans);
    for (int i = 1; i <= N; i++) {
      for (int j = 1; j <= M; j++) { Ans[i][j] = calc(i, j); }
    }
    int ans = 0;
    for (int i = 1; i <= N; i++) {
      for (int j = 1; j <= M; j++) {
        if (Ans[i][j]) { ans = 1; }
      }
    }
    if (ans == 1) {
      printf("YES\n");
    } else {
      printf("NO\n");
    }
  }
  return 0;
