void add_to_queue(int i, int j, int v, int distance, string path) {
  if (distance[i][j][v] > distance || (distance[i][j][v] == distance && backtrack[i][j][v] > path)) {
    distance[i][j][v] = distance;
    backtrack[i][j][v] = path;
    queue_i[last_added] = i;
    queue_j[last_added] = j;
    queue_v[last_added] = v;
    result[last_added] = path;
    last_added++;
  }
}

