PII findCycle(const VVI &adj) {
  int numVertices = SIZE(adj);
  VI visited(numVertices, false);
  VI path;
  FOR(i, numVertices) {
    if (!visited[i]) {
      PII cycle = findCycle(adj, i, -1, visited, path);
      if (cycle.first != -1) return cycle;
    }
  }
  return MP(-1, -1);
}

PII findCycle(const VVI &adj, int node, int prev, VI &visited, VI &path) {
  visited[node] = true;
  path.PB(node);
  FOR(i, SIZE(adj[node])) {
    int neighbor = adj[node][i];
    if (neighbor == prev) continue;
    if (visited[neighbor]) {
      return MP(neighbor, node);
    }
    PII cycle = findCycle(adj, neighbor, node, visited, path);
    if (cycle.first != -1) return cycle;
  }
  path.pop_back();
  visited[node] = false;
  return MP(-1, -1);
}

