using namespace std;

int main() {
  int numberOfTestCases;
  cout << "Enter the number of test cases: ";
  cin >> numberOfTestCases;
  for (int testCaseNumber = 1; testCaseNumber <= numberOfTestCases; testCaseNumber++) {
    int n, A, B, C, D, xInitial, yInitial, M;
    cout << "Enter the values for n, A, B, C, D, x0, y0, and M: ";
    cin >> n >> A >> B >> C >> D >> xInitial >> yInitial >> M;
    int x[n], y[n];
    x[0] = xInitial;
    y[0] = yInitial;
    for (int i = 1; i < n; i++) {
      x[i] = (A * x[i - 1] + B) % M;
      y[i] = (C * y[i - 1] + D) % M;
    }
    int answer = 0;
    for (int i = 0; i < n; i++) {
      for (int j = i + 1; j < n; j++) {
        for (int k = j + 1; k < n; k++) {
          if ((x[i] + x[j] + x[k]) % 3 == 0 &&
              (y[i] + y[j] + y[k]) % 3 == 0) {
            answer++;
          }
        }
      }
    }
    cout << "Case #" << testCaseNumber << ": " << answer << endl;
  }
  return 0;
}
